    theme_light: "Light",
    heroHeadline: "Your most private photos and videos, only for the people you choose.",
    heroSubtitle: "In messaging apps or social networks, sending a photo means giving away a copy or accepting murky terms where it's never clear who really owns your content. In XowApp that NEVER happens: what you show is always yours, you are always in charge, and XowApp does not want to and—most importantly—cannot even see what you share with other users. Nobody can forward it, save it to their camera roll, or take screenshots. And when you delete it, it vanishes from every phone instantly.",
    hero_manifesto: "It's \"SHOWING\", not sharing. The owner stays in control.",
    whatis_kicker: "What XowApp is",
    whatis_title: "Showing your photos and videos, not giving them away",
    whatis_body: "XowApp was created to solve the privacy crisis in social media and messaging apps: where platforms impose dubious terms on the ownership of your images and you lose all control the moment you hit send. In XowApp you don't hand out files for others to hoard: we model the natural act of showing someone your phone. What enters XowApp never leaves XowApp. Photos travel encrypted directly between devices into an isolated private sandbox. No one can extract or screenshot them, and whatever you upload remains 100% yours: the owner is always in control.",
    how_kicker: "How it works",
    how_title: "Three principles, zero complications",
    how_step1_title: "1. Absolute anonymity by design",
    how_step1_body: "Nobody can know who is behind each user—not even XowApp. We do not collect your personal data and we don't need it to provide the service.",
    how_step2_title: "2. Show without giving away copies",
    how_step2_body: "Your photos travel encrypted from device to device into an isolated app space. They cannot be exported, saved to camera roll, or screenshotted.",
    how_step3_title: "3. The owner stays in control",
    how_step3_body: "You decide who sees your photos and for how long. If you delete an item from your album, it is instantly erased from every device.",
    how_cta_prompt: "If you want to dive deeper into how we protect your photos step by step:",
    how_cta_deepdive: "See how it works",
    deepdive_kicker: "How XowApp works",
    deepdive_title: "Show photos with absolute freedom: no copies, no screenshots, total control",
    deepdive_intro: "XowApp lets you show your photos and videos to the people you choose with complete peace of mind. What enters XowApp never leaves XowApp: no one can save them to their camera roll, forward them, or share them outside.",
    deepdive_concept_showing_title: "Showing vs. Sharing",
    deepdive_concept_showing_body: "In standard messaging apps and social media, sending a photo gives away a digital copy and binds you to ambiguous terms about your content. In XowApp we model the natural act of showing: like letting someone look at a photo album in your hands. They look, but the album stays yours. XowApp cannot see your photos or messages, screenshots and downloads are blocked, and you retain total control at all times.",
    deepdive_concept_albums_title: "Private and group albums: The owner stays in control",
    deepdive_concept_albums_body: "Create private albums for two or group albums with friends and family. Whoever uploads a photo remains its sole owner: if you choose to delete it at any time, it is instantly wiped from every member's device.",
    deepdive_concept_social_title: "100% private reactions and chat",
    deepdive_concept_social_body: "Comment, react, and chat inside each album. All comments, likes, and messages travel end-to-end encrypted and are strictly visible only to authorized album members.",
    deepdive_concept_security_title: "Absolute anonymity by design and isolated sandbox",
    deepdive_concept_security_body: "We do not know who you are and have no way to find out. Your photos are stored in an isolated private sandbox on your phone, optionally locked with biometrics. Neither other apps nor our servers can ever access your content.",
    usecases_kicker: "Step by step",
