    usecase1_body: "Ana simply picks a display name, an avatar, and her @handle (e.g. @ana). We don't ask for a phone number, email, or passwords. Strangers on the internet cannot search her profile or find her photos.",
    usecase1_flow_step1_title: "1. Name & Username",
