    usecase1_flow_step3_title: "3. Private profile",
    usecase1_flow_step3_desc: "Nobody unknown online can find you.",
    usecase2_tag: "Step 2",
    usecase2_title: "2. Connect with a friend or family member",
    usecase2_badge: "Direct connection",
    usecase2_body: "To send photos to each other, Alice and Bob connect. They can search for Bob's username (@bob), send an invite link via chat, or scan a QR code if they are together. Their phones are linked privately and directly.",
    usecase2_flow_step1_title: "1. Search or scan QR",
