    usecase3_tag: "Step 3",
    usecase3_title: "3. Showing photos inside a private album",
    usecase3_badge: "In-app viewing only",
    usecase3_body: "Ana adds a photo to her album with Carlos. The image travels encrypted directly from her phone to Carlos's, landing strictly in XowApp's private storage. The server merely bridges the delivery and purges the encrypted file immediately upon download. Carlos can view the photo, but cannot save it, forward it, or take screenshots.",
    usecase3_flow_step1_title: "1. Alice adds photo",
