    profile_delete_button: "Delete all my data",
    profile_delete_modal_title: "Delete your account permanently?",
    profile_delete_modal_body: "This will permanently delete your account, your albums, sent and received transfers, contacts, comments, likes and messages from our servers. This cannot be undone. Moderation reports associated with your account are not deleted.",
    profile_delete_modal_confirm_label: "To confirm, type the part of your email before the \"@\":",
