    donar_kicker: "Donar",
    donar_title: "Apoya a que XowApp siga viva e independiente",
    donar_intro: "XowApp no vive de tus datos ni de publicidad. Se financia exclusivamente gracias a personas que valoran su privacidad y deciden apoyar los costes de los servidores. Cada donación se asigna de forma transparente a las fases del proyecto.",
