    donar_tier_blurb_2: "Un pequeño empujón -- como invitarnos a un café.",
    donar_tier_blurb_5: "Ahora sí. Una ronda de cafés para todo el equipo.",
    donar_tier_blurb_10: "Sólido. Un capricho para ti y para nosotros.",
