    donar_quote_heart: "Tu privacidad no se vende, pero nuestro corazón sí se conmueve con tu apoyo. ¡Ponle un poco de amor a XowApp!",
    donar_quote_rocket: "La privacidad de tus recuerdos no tiene límites. ¡Sé el combustible que impulse a XowApp hacia las estrellas!",
    donar_quote_handshake: "Sin trampa ni cartón: tú cuidas tus fotos y nosotros cuidamos la app. ¡Hagamos un trato y colabora hoy!",
    donar_quote_gift: "El regalo de la privacidad es para todos, pero mantenerlo requiere esfuerzo. ¡Hazle un regalo a XowApp!",
