    profile_userid_label: "Nombre de usuario",
    profile_danger_zone_title: "Zona de peligro",
    profile_danger_zone_desc: "Borra permanentemente tu cuenta de XowApp y todo lo asociado a ella de nuestros servidores. Esta acción no se puede deshacer.",
    profile_delete_button: "Borrar todos mis datos",
    profile_delete_modal_title: "¿Borrar tu cuenta de forma permanente?",
    profile_delete_modal_body: "Esto borrará de forma permanente tu cuenta, tus álbumes, los envíos enviados y recibidos, tus contactos, comentarios, me gusta y mensajes de nuestros servidores. Esta acción no se puede deshacer. Los reportes de moderación asociados a tu cuenta no se eliminan.",
    profile_delete_modal_confirm_label: "Para confirmar, escribe la parte de tu correo antes de la \"@\":",
