    transparencia_breakdown_allocated_label: "Fondi Assegnati",
    transparencia_breakdown_no_expenses: "Budget stimato in base alla pianificazione operativa attuale.",
    transparencia_cta_donar: "Vuoi aiutare? Vai alla pagina delle donazioni",
    donar_kicker: "Donare",
    donar_title: "Aiuta XowApp a restare viva e indipendente",
    donar_intro: "XowApp non vive dei tuoi dati né di pubblicità. È finanziata esclusivamente dalle persone che hanno a cuore la propria privacy e sostengono i costi dei server. Ogni donazione è trasparente e assegnata alle fasi del progetto.",
    donar_stripe_notice: "I pagamenti con carta arriveranno molto presto. Nel frattempo, puoi donare direttamente dall'app (Google Play / App Store).",
    donar_stripe_cta_disabled: "Dona con carta (prossimamente)",
    donar_tier_note: "Questi sono gli stessi importi che vedrai dentro l'app.",
    donar_amount_hint: "Scorri per scegliere un importo",
    donar_tier_blurb_2: "Una piccola spinta -- come offrirci un caffè.",
    donar_tier_blurb_5: "Questo sì che è bello. Un giro di caffè per tutto il team.",
    donar_tier_blurb_10: "Solido! Un piccolo sfizio, per te e per noi.",
    donar_tier_blurb_15: "Generoso! Sei ufficialmente tra i buoni.",
    donar_tier_blurb_30: "Wow, che signore! Quasi arrossiamo.",
    donar_tier_blurb_100: "100€?! È magnificamente esagerato. Ti adoriamo per questo (ma sul serio, sei sicuro?).",
    donar_quote_coffee: "Ogni grande app funziona a caffeina. Offrici un caffè e tieni i nostri server ben svegli!",
    donar_quote_pizza: "Il codice migliore nasce con il formaggio fuso. Offrici una fetta per alimentare la tua privacy!",
    donar_quote_heart: "La tua privacy non è in vendita, ma il nostro cuore si scioglie per il tuo supporto. Dona un po' d'amore a XowApp!",
    donar_quote_rocket: "I tuoi ricordi privati meritano una sicurezza spaziale. Sii il carburante che lancia XowApp verso le stelle!",
    donar_quote_handshake: "Senza inganni: tu tieni le tue foto, noi curiamo la tecnologia. Stringiamoci la mano e sostieni il progetto!",
    donar_quote_gift: "La privacy è un regalo per tutti, ma mantenerla richiede impegno. Fai un regalo a XowApp!",
    donar_quote_piggy: "Il nostro salvadanaio non serve a arricchirci, ma a pagare i server. Metti qualche moneta nel maialino!",
    donar_thanks_title: "Grazie, davvero",
    donar_thanks_body: "Ogni contributo, anche modesto, aiuta a mantenere i server attivi e garantisce che XowApp rimanga uno spazio 100% privato, anonimo e libero da interessi commerciali.",
