    theme_dark: "Dunkel",
    theme_light: "Hell",
    heroHeadline: "Deine privatesten Fotos und Videos – nur für die Menschen, die du wählst.",
    heroSubtitle: "In Messenger-Apps oder sozialen Netzwerken verschenkst du beim Senden eines Fotos eine Kopie oder akzeptierst unklare Bedingungen darüber, wer eigentlich Eigentümer deiner Inhalte ist. Bei XowApp passiert das NICHT: Was du zeigst, gehört immer dir, du hast das Sagen, und XowApp will und – vor allem – kann nicht einmal sehen, was du mit anderen teilst. Niemand kann es weiterleiten, in der Galerie speichern oder Screenshots machen. Und wenn du es löschst, verschwindet es sofort von allen Geräten.",
    hero_manifesto: "Es heißt «ZEIGEN», nicht teilen. Der Eigentümer entscheidet.",
    whatis_kicker: "Was XowApp ist",
    whatis_title: "Fotos und Videos zeigen – nicht verteilen",
    whatis_body: "XowApp wurde geschaffen, um das Privatsphäre-Problem in sozialen Netzwerken und Messenger-Apps zu lösen: Wo Plattformen undurchsichtige Bedingungen über das Eigentum an deinen Bildern stellen und du in der Sekunde des Sendens die Kontrolle verlierst. Bei XowApp verteilst du keine Dateien zur dauerhaften Speicherung: Wir bilden das natürliche Zeigen des Smartphones in der Hand nach. Was in XowApp hineingeht, verlässt XowApp nicht. Bilder reisen verschlüsselt von Gerät zu Gerät in den isolierten privaten App-Speicher. Niemand kann sie exportieren oder abfotografieren, und was du hochlädst, bleibt zu 100% deins: Der Eigentümer entscheidet.",
    how_kicker: "So funktioniert es",
    how_title: "Drei Prinzipien, null Komplikationen",
    how_step1_title: "1. Absolute Anonymität durch Design",
    how_step1_body: "Niemand weiß, welche reale Person hinter einem Konto steht – nicht einmal XowApp. Wir verlangen keine persönlichen Daten und brauchen sie nicht, um den Dienst bereitzustellen.",
    how_step2_title: "2. Zeigen ohne Kopien zu verschenken",
    how_step2_body: "Deine Fotos reisen verschlüsselt von Gerät zu Gerät. Sie bleiben im privaten Speicher der App isoliert: Sie können nicht exportiert, in der Galerie gespeichert oder per Screenshot erfasst werden.",
    how_step3_title: "3. Der Eigentümer entscheidet",
    how_step3_body: "Du entscheidest, wer was sieht und wie lange. Wenn du ein Foto aus deinem Album löschst, wird es sofort auf allen Geräten vollständig entfernt.",
    how_cta_prompt: "Wenn du im Detail erfahren möchtest, wie wir deine Fotos Schritt für Schritt schützen:",
