    deepdive_kicker: "Wie XowApp funktioniert",
    deepdive_title: "Fotos in voller Freiheit zeigen: Keine Kopien, keine Screenshots, volle Kontrolle",
    deepdive_intro: "Mit XowApp kannst du deine Fotos und Videos ganz unbesorgt den Personen zeigen, die du auswählst. Was in XowApp hineingeht, verlässt XowApp nicht: Niemand kann sie in der Galerie speichern oder nach außen weiterleiten.",
    deepdive_concept_showing_title: "Zeigen statt Teilen",
    deepdive_concept_showing_body: "Bei herkömmlichen Messenger-Apps und sozialen Netzwerken übergibst du beim Senden eine digitale Kopie und willigst in zweideutige Nutzungsbedingungen ein. Bei XowApp bilden wir das natürliche Zeigen nach: wie ein Fotobuch in deiner Hand. Der andere schaut hinein, aber das Album bleibt bei dir. XowApp kann weder deine Fotos noch deine Nachrichten einsehen, Downloads und Screenshots sind unmöglich, und du behältst jederzeit die volle Kontrolle.",
    deepdive_concept_albums_title: "Private Alben & Gruppenalben: Der Eigentümer entscheidet",
    deepdive_concept_albums_body: "Erstelle private Alben zu zweit oder Gruppenalben für Freunde und Familie. Wer ein Foto hochlädt, bleibt dessen alleiniger Eigentümer: Wenn du es löschst, verschwindet es sofort von den Geräten aller Mitglieder.",
    deepdive_concept_social_title: "100% private Reaktionen & Chat",
    deepdive_concept_social_body: "Kommentiere, reagiere und unterhalte dich innerhalb jedes Albums. Alle Kommentare, Likes und Nachrichten reisen Ende-zu-Ende verschlüsselt und sind nur für berechtigte Album-Mitglieder sichtbar.",
    deepdive_concept_security_title: "Absolute Anonymität & isolierter Speicher",
    deepdive_concept_security_body: "Wir wissen nicht, wer du bist, und können es nicht herausfinden. Deine Fotos liegen im isolierten, privaten App-Speicher deines Telefons, geschützt durch Biometrie. Weder andere Apps noch unsere Server haben Zugriff.",
    usecases_kicker: "Schritt für Schritt",
