    usecase1_tag: "Schritt 1",
    usecase1_title: "1. Konto in absoluter Anonymität erstellen*",
    usecase1_badge: "Schnell & privat",
    usecase1_body: "Ana wählt einfach ihren Anzeigenamen, ein Profilbild und ihren @Benutzernamen (z.B. @ana). Wir verlangen weder Telefonnummer, E-Mail noch Passwörter. Fremde im Internet können ihr Profil weder finden noch einsehen.",
