    usecase2_badge: "Direkte Verbindung",
    usecase2_body: "Um sich Fotos zu senden, verbinden sich Anna und Felix. Das geht über Felix' Benutzernamen (@felix), per Einladungslink im Chat oder durch Scannen eines QR-Codes vor Ort. Ihre Geräte werden direkt und privat gekoppelt.",
    usecase2_flow_step1_title: "1. Suchen oder scannen",
