    usecase3_tag: "Schritt 3",
    usecase3_title: "3. Fotos in einem privaten Album zeigen",
    usecase3_badge: "Nur in der App",
    usecase3_body: "Ana fügt ein Foto zu ihrem Album mit Carlos hinzu. Das Bild reist verschlüsselt von ihrem Smartphone zu Carlos und landet ausschließlich im privaten Speicher von XowApp. Der Server dient nur als Weiterleitung und löscht die verschlüsselte Datei nach der Zustellung sofort. Carlos kann das Foto ansehen, aber nicht speichern, weiterleiten oder Screenshots machen.",
    usecase3_flow_step1_title: "1. Anna fügt Foto hinzu",
