    profile_email_label: "E-Mail",
    profile_email_info_tooltip: "Das ist die E-Mail-Adresse, mit der du dich auf der Website angemeldet hast. XowApp speichert sie nirgendwo.",
    profile_userid_label: "Benutzername",
    profile_danger_zone_title: "Gefahrenzone",
    profile_danger_zone_desc: "Lösche dein XowApp-Konto und alles, was damit verknüpft ist, dauerhaft von unseren Servern. Dies kann nicht rückgängig gemacht werden.",
    profile_delete_button: "Alle meine Daten löschen",
    profile_delete_modal_title: "Konto dauerhaft löschen?",
    profile_delete_modal_body: "Dadurch werden dein Konto, deine Alben, gesendete und empfangene Übertragungen, deine Kontakte, Kommentare, Likes und Nachrichten dauerhaft von unseren Servern gelöscht. Dies kann nicht rückgängig gemacht werden. Moderationsmeldungen, die mit deinem Konto verknüpft sind, werden nicht gelöscht.",
