    transparencia_breakdown_allocated_label: "Fonduri Alocate",
    transparencia_breakdown_no_expenses: "Buget estimat pe baza planificării operaționale actuale.",
    transparencia_cta_donar: "Vrei să ajuți? Mergi la pagina de donații",
    donar_kicker: "Donează",
    donar_title: "Ajută XowApp să rămână vie și independentă",
    donar_intro: "XowApp nu trăiește din datele tale sau din reclame. Este finanțată exclusiv de oameni care își prețuiesc intimitatea și susțin costurile serverelor. Fiecare donație este alocată transparent etapelor proiectului.",
    donar_stripe_notice: "Plățile cu cardul vor fi disponibile foarte curând. Între timp, poți dona direct din aplicație (Google Play / App Store).",
    donar_stripe_cta_disabled: "Donează cu cardul (în curând)",
    donar_tier_note: "Acestea sunt aceleași sume pe care le vei vedea în aplicație.",
    donar_amount_hint: "Glisează pentru a alege o sumă",
    donar_tier_blurb_2: "Un mic imbold -- ca și cum ne-ai oferi o cafea.",
    donar_tier_blurb_5: "Acum vorbim! O rundă de cafele pentru toată echipa.",
    donar_tier_blurb_10: "Solid! Un mic răsfăț, pentru tine și pentru noi.",
    donar_tier_blurb_15: "Generos! Ești oficial printre cei buni.",
    donar_tier_blurb_30: "Uau, mare domn! Aproape că roșim.",
    donar_tier_blurb_100: "100€?! E minunat de exagerat. Te iubim pentru asta (dar serios, ești sigur?).",
    donar_quote_coffee: "Fiecare aplicație grozavă funcționează pe bază de cafeină. Cinstește-ne cu o cafea și ține serverele noastre treze!",
    donar_quote_pizza: "Cel mai bun cod este alimentat de brânză topită. Cinstește-ne cu o felie și ține confidențialitatea crocantă!",
    donar_quote_heart: "Confidențialitatea ta nu este de vânzare, dar inima noastră se topește la sprijinul tău. Trimite puțină dragoste către XowApp!",
    donar_quote_rocket: "Amintirile tale private merită o securitate spațială. Fii combustibilul care propulsează XowApp către stele!",
    donar_quote_handshake: "Fără trucuri: tu îți păstrezi fotografiile, noi protejăm tehnologia. Bate palma cu noi și susține proiectul!",
    donar_quote_gift: "Confidențialitatea este un cadou pentru toți, dar menținerea ei necesită efort. Oferă un cadou pentru XowApp!",
    donar_quote_piggy: "Pușculița noastră nu este pentru profit, ci pentru a plăti serverele. Aruncă câteva monede în purceluș!",
