    profile_danger_zone_desc: "Șterge definitiv contul tău XowApp și tot ce este asociat cu el de pe serverele noastre. Această acțiune nu poate fi anulată.",
    profile_delete_button: "Șterge toate datele mele",
    profile_delete_modal_title: "Ștergi definitiv contul tău?",
    profile_delete_modal_body: "Această acțiune va șterge definitiv contul tău, albumele tale, transferurile trimise și primite, contactele, comentariile, aprecierile și mesajele tale de pe serverele noastre. Această acțiune nu poate fi anulată. Rapoartele de moderare asociate contului tău nu sunt șterse.",
