    donar_title: "Hjælp med at holde XowApp i live",
    donar_intro: "XowApp kører ikke på dine data eller reklamer. Det kører på, at de mennesker, der bruger det, beslutter at hjælpe med at betale for det. Hver donation går direkte ind i en af de 3 faser, du kan se på siden med projektstatus.",
    donar_stripe_notice: "Kortbetalinger kommer meget snart. I mellemtiden kan du donere direkte fra appen (Google Play / App Store).",
    donar_stripe_cta_disabled: "Donér med kort (kommer snart)",
