    donar_tier_blurb_100: "100 €?! Det er vidunderligt overdrevet. Vi elsker dig for det (men er du helt sikker?).",
    donar_quote_coffee: "Enhver god app kører på koffein. Giv os en kop kaffe og hold vores servere lysvågne!",
    donar_quote_pizza: "Den bedste kode laves med smeltet ost. Støt XowApp med en skive og hold privatlivet ekstra sprødt!",
    donar_quote_heart: "Dit privatliv er ikke til salg, men vores hjerter smelter bestemt over din støtte. Send XowApp lidt kærlighed!",
    donar_quote_rocket: "Private minder fortjener sikkerhed i verdensklasse. Vær den raketbrændstof, der skyder XowApp mod stjernerne!",
    donar_quote_handshake: "Ingen skjulte betingelser: du ejer dine billeder, vi passer på teknologien. Giv os hånden og støt projektet!",
